from itertools import product

# Generate all possible binary sequences of length 11
sequences = list(product([-1, 1], repeat=11))

# Filter sequences based on the given constraints
valid_sequences = []
for seq in sequences:
    if seq[1] == 1 and seq[8] == 1:
        c = [0] * 11
        for k in range(1, 11):
            for i in range(11 - k):
                c[k] += seq[i] * seq[i + k]
        if c[6] == 0 and c[9] == 1 and sum([c_k**2 for c_k in c[1:]]) <= 23:
            valid_sequences.append(seq)

# Print the first valid sequence or "UNSATISFIABLE" if no sequence exists
if valid_sequences:
    print(valid_sequences[0])
else:
    print("UNSATISFIABLE")
